nativeSource:
{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
  .e1 { stroke: --teal-deep; }
  .e2 { stroke: --teal-deep; }
  .e3 { stroke: --teal-deep; }
}
|group#visual| "V7 · Bounded handler access" { layout: grid; columns: repeat(2); gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "Isolated handler" { width: 240; } [
    |cell#detail| "No raw SQL connection, database\ncredentials, ambient network or broad\nhost mount. Only declared transaction\ncapabilities."
  ]
  |box#n2| "Controlled gateway" { width: 240; } [
    |cell#detail| "Freeze canonical identities. Check\nevery attempted read/write before\nstorage access. Returning state to its\nold value cannot hide an attempt."
  ]
  |box#n3| "Consumer-owned transaction" { width: 240; } [
    |cell#detail| "Authorization, native invariant\nchecks, replay ledger and outbox are\ncontrol responsibilities. Their reads\nare not handler permissions."
  ]
  |box#n4| "Commit or rollback" { width: 240; } [
    |cell#detail| "Verify outputs, constraints, frame and\npostconditions. Failure aborts the\nwhole attempted transaction; no\npartial business outcome."
  ]
  n1 -> n2 "Bounded authenticated capability RPC" .e1 { along: 0.35; }
  n2 -> n3 "Check attempts before storage" .e2 { along: 0.5; }
  n3 -> n4 "Verify before commit" .e3 { along: 0.65; }
]
